/**
 * Template execution smoke check, not a browser/DOM-layout test. A deliberately
 * minimal document records the HTML generated by the real rendering functions.
 * Native DOM reconciliation, focus, touch, layout and drawing need browser QA.
 */
import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { Player, sim } from './ea-player.mjs';
import { normalRun } from './ea-normal-play.mjs';
import { createEAUI, EA_SHELL } from '../dist/ea-ui.mjs';

// The template harness calls simulation functions directly, so separately check
// that the application's real dispatch gate accepts commands exposed by the UI.
// This caught a live button whose new simulation command was missing from the app.
const [uiSource, appSource] = await Promise.all([
  readFile(new URL('../dist/ea-ui.mjs', import.meta.url), 'utf8'),
  readFile(new URL('../dist/ea-game.mjs', import.meta.url), 'utf8'),
]);
const declaration = appSource.match(/const allowed=new Set\(\[([^\]]+)\]\)/)?.[1];
assert.ok(declaration, 'Locate the real application command dispatch gate');
const allowed = new Set([...declaration.matchAll(/'([^']+)'/g)].map(match => match[1]));
const exposedCommands = new Set([
  ...uiSource.matchAll(/\bact\(\s*'([^']+)'/g),
  ...uiSource.matchAll(/\bbtn\([^,\n]*,\s*'([^']+)'/g),
].map(match => match[1]).filter(name => typeof sim[name] === 'function'));
for (const name of exposedCommands) assert.ok(allowed.has(name), `UI command ${name} is rejected by the real application`);

const fragments = [], nodes = new Map(), listeners = new Map();
const fakeNode = () => ({
  childNodes: [], textContent: '', scrollTop: 0, dataset: {}, style: {}, open: false,
  classList: { toggle() {}, add() {}, remove() {}, contains() { return false; } },
  setAttribute() {}, removeAttribute() {}, addEventListener() {}, scrollIntoView() {},
  querySelector() { return fakeNode(); }, querySelectorAll() { return []; },
});
globalThis.window = { matchMedia: () => ({ matches: false }) };
globalThis.document = {
  activeElement: null,
  body: fakeNode(),
  createElement(name) {
    assert.equal(name, 'template');
    return { set innerHTML(html) { fragments.push(html); }, content: { childNodes: [] } };
  },
  querySelector(selector) { if (!nodes.has(selector)) nodes.set(selector, fakeNode()); return nodes.get(selector); },
  querySelectorAll() { return []; },
  addEventListener(name, handler) { listeners.set(name, handler); },
};

let state = sim.initial(), tab = 'self';
const ui = createEAUI({
  getState: () => state, getTab: () => tab, setTab: value => { tab = value; },
  act(name, ...args) { assert.equal(typeof sim[name], 'function', `UI invoked missing game command ${name}`); return sim[name](state, ...args); },
  openModal(title, html) { fragments.push(html); document.querySelector('#modal-title').textContent = title; },
  closeModal() {}, toast() {}, getSelection: () => null, chooseBuild() {}, getScene: () => 'map',
});
const tabs = ['self', 'build', 'disciples', 'manuals', 'production', 'sect', 'explore', 'journal'];
const rows = [];
function renderScenario(label, candidate) {
  state = candidate;
  const before = structuredClone(state);
  for (const current of tabs) {
    tab = current;
    const start = fragments.length;
    ui.render();
    const html = fragments.slice(start).join('');
    assert.ok(html.length > 100, `${label}/${tab} must actually evaluate a page template`);
    assert.doesNotMatch(html, /\bNaN\b|\[object Object\]/, `${label}/${tab} invalid visible values`);
    rows.push({ scenario: label, tab, htmlCharacters: html.length });
  }
  for (const disciple of state.disciples.slice(0, 3)) ui.openPerson(disciple.id);
  for (const building of state.buildings.slice(0, 3)) ui.renderDetail({ kind: 'building', id: building.id });
  ui.openGuide();
  assert.deepEqual(state, before, `${label} renders do not mutate simulation`);
}

assert.ok(EA_SHELL.includes('id="save-status"') && EA_SHELL.includes('id="settings"'));
renderScenario('new game', sim.initial());
renderScenario('first chapter', new Player().chapterOne().state);
renderScenario('30 people, 40 buildings, two peaks, completed story', normalRun({ reference: true }).state);
const journey = new Player().foundation().prepareRevenge();
renderScenario('qixia interaction', journey.state);
journey.action('resolveExploration', 'challenge');
renderScenario('active final combat', journey.state);
journey.tick(100);
renderScenario('battle defeat and recovery', journey.state);
await writeFile(new URL('./ea-ui-template-report.json', import.meta.url), JSON.stringify({
  limitation: 'Real template evaluation with a minimal recording document. No browser layout, focus, pointer, mobile or FPS claims.',
  dispatchCommandsChecked: [...exposedCommands].sort(),
  rendered: rows,
}, null, 2) + '\n');
console.log(JSON.stringify({ checked: rows.length, scenarios: new Set(rows.map(x => x.scenario)).size, result: 'templates executed without exceptions or visible nonfinite values; state unchanged' }, null, 2));
